-- ════════════════════════════════════════════════════════════════════════════
--  Partner group: BR Digital — account manager Carol Oren.
--  Paste into the SQL Editor and Run. Safe to re-run: the group is created
--  once; re-running only refreshes its brand color and logo.
--
--  · AM name/email are copied from Carol's existing groups so the dashboard's
--    AM filter lists BR Digital under the same name (falls back to
--    "Carol Oren" / carol@44idigital.com if no existing group matches).
--  · The logo is stored inline (an embedded SVG image), so it shows in the
--    console and on the client report cover with no file hosting.
--    Source file: docs/partner-logos/br-digital.svg
--  · Trello board and IO recipients are left blank — set them later with an
--    UPDATE on partner_groups when known.
-- ════════════════════════════════════════════════════════════════════════════
insert into partner_groups (name, am_name, am_email, brand_color, brand_color_2, logo_url)
select
  'BR Digital',
  coalesce((select am_name  from partner_groups where am_name ilike 'carol%' order by am_name limit 1), 'Carol Oren'),
  coalesce((select am_email from partner_groups where am_name ilike 'carol%' and coalesce(am_email,'') <> '' limit 1), 'carol@44idigital.com'),
  '#DE2128', '#000000',
  'data:image/svg+xml;base64,'
where not exists (select 1 from partner_groups where lower(name) = 'br digital');

update partner_groups
   set brand_color = '#DE2128', brand_color_2 = '#000000',
       logo_url = 'data:image/svg+xml;base64,'
 where lower(name) = 'br digital';

select id, name, am_name, am_email, brand_color, length(logo_url) as logo_bytes
  from partner_groups where lower(name) = 'br digital';
